const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

pub const HyperNode = struct {
    id: u64,
    activation: f64,
    meta_parameters: [16]f64,
    connections: ArrayList(u64),
    learning_rate: f64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, id: u64) !HyperNode {
        var connections = ArrayList(u64).init(allocator);
        var meta_params: [16]f64 = undefined;

        var prng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp() +% id));
        const rand = prng.random();

        for (&meta_params) |*p| {
            p.* = (rand.float(f64) - 0.5) * 0.1;
        }

        return HyperNode{
            .id = id,
            .activation = 0.0,
            .meta_parameters = meta_params,
            .connections = connections,
            .learning_rate = 0.001,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *HyperNode) void {
        self.connections.deinit();
    }

    pub fn mutate(self: *HyperNode, strength: f64) void {
        var prng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp() +% self.id));
        const rand = prng.random();

        for (&self.meta_parameters) |*p| {
            const delta = (rand.float(f64) - 0.5) * strength;
            p.* += delta;
            p.* = @max(-1.0, @min(1.0, p.*));
        }
    }

    pub fn forward(self: *HyperNode, inputs: []const f64) f64 {
        var sum: f64 = 0.0;
        var i: usize = 0;
        while (i < inputs.len) : (i += 1) {
            const param_idx = i % self.meta_parameters.len;
            sum += inputs[i] * self.meta_parameters[param_idx];
        }
        self.activation = 1.0 / (1.0 + @exp(-sum));
        return self.activation;
    }
};

pub const HyperGraph = struct {
    nodes: ArrayList(HyperNode),
    adjacency: ArrayList(ArrayList(usize)),
    allocator: Allocator,
    generation: u64,

    pub fn init(allocator: Allocator, num_nodes: usize) !HyperGraph {
        var nodes = ArrayList(HyperNode).init(allocator);
        var adjacency = ArrayList(ArrayList(usize)).init(allocator);

        var i: usize = 0;
        while (i < num_nodes) : (i += 1) {
            const node = try HyperNode.init(allocator, i);
            try nodes.append(node);

            var adj_list = ArrayList(usize).init(allocator);
            try adjacency.append(adj_list);
        }

        return HyperGraph{
            .nodes = nodes,
            .adjacency = adjacency,
            .allocator = allocator,
            .generation = 0,
        };
    }

    pub fn deinit(self: *HyperGraph) void {
        for (self.nodes.items) |*node| {
            node.deinit();
        }
        self.nodes.deinit();

        for (self.adjacency.items) |*adj| {
            adj.deinit();
        }
        self.adjacency.deinit();
    }

    pub fn addEdge(self: *HyperGraph, from: usize, to: usize) !void {
        if (from >= self.nodes.items.len or to >= self.nodes.items.len) return error.InvalidIndex;
        try self.adjacency.items[from].append(to);
        try self.nodes.items[from].connections.append(to);
    }

    pub fn evolve(self: *HyperGraph, fitness: f64) !void {
        self.generation += 1;

        var prng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp() +% self.generation));
        const rand = prng.random();

        const mutation_rate = if (fitness > 0.8) 0.01 else 0.1;

        for (self.nodes.items) |*node| {
            if (rand.float(f64) < mutation_rate) {
                node.mutate(0.05);
            }
        }
    }

    pub fn propagate(self: *HyperGraph) !void {
        const num_nodes = self.nodes.items.len;
        var activations = try self.allocator.alloc(f64, num_nodes);
        defer self.allocator.free(activations);

        for (activations) |*a| {
            a.* = 0.0;
        }

        var i: usize = 0;
        while (i < self.nodes.items.len) : (i += 1) {
            if (self.adjacency.items[i].items.len > 0) {
                var inputs = try self.allocator.alloc(f64, self.adjacency.items[i].items.len);
                defer self.allocator.free(inputs);

                var j: usize = 0;
                while (j < self.adjacency.items[i].items.len) : (j += 1) {
                    const neighbor_idx = self.adjacency.items[i].items[j];
                    inputs[j] = self.nodes.items[neighbor_idx].activation;
                }

                activations[i] = self.nodes.items[i].forward(inputs);
            }
        }

        i = 0;
        while (i < self.nodes.items.len) : (i += 1) {
            self.nodes.items[i].activation = activations[i];
        }
    }
};

pub const ASIController = struct {
    hyper_graph: HyperGraph,
    fitness_history: ArrayList(f64),
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_nodes: usize) !ASIController {
        const graph = try HyperGraph.init(allocator, num_nodes);
        var history = ArrayList(f64).init(allocator);

        return ASIController{
            .hyper_graph = graph,
            .fitness_history = history,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ASIController) void {
        self.hyper_graph.deinit();
        self.fitness_history.deinit();
    }

    pub fn optimize(self: *ASIController, target_fitness: f64, max_iterations: usize) !void {
        var iteration: usize = 0;
        while (iteration < max_iterations) : (iteration += 1) {
            try self.hyper_graph.propagate();

            var total_activation: f64 = 0.0;
            for (self.hyper_graph.nodes.items) |node| {
                total_activation += @abs(node.activation);
            }

            const fitness = total_activation / @as(f64, @floatFromInt(self.hyper_graph.nodes.items.len));
            try self.fitness_history.append(fitness);

            if (fitness >= target_fitness) {
                break;
            }

            try self.hyper_graph.evolve(fitness);
        }
    }
};

